import React from "react";
import ChatList from "./components/ChatList";
import Conversation from "./components/Conversation";
import "./styles.css";
export default function App(){const [state,setState]=React.useState(null);React.useEffect(()=>window.chatter.subscribe(setState,{navigation:true}),[]);if(!state)return <p>Loading…</p>;return state.view==="home"?<ChatList state={state}/>:<Conversation state={state}/>;}

