import React from "react";
import Markdown from "react-markdown";
import remarkGfm from "remark-gfm";
import Composer from "./Composer";
export default function Conversation({state}){return <main><header><button onClick={()=>window.chatter.showHome()}>{state.labels.allChats}</button><button onClick={()=>window.chatter.openConversation()}>…</button></header>{state.hasOlderMessages&&<button disabled={state.olderMessagesLoading} onClick={()=>window.chatter.loadOlderMessages()}>{state.labels.loadMore}</button>}<section className="messages">{state.messages.filter(message=>message.content.trim()).map(message=><article key={message.id} data-role={message.role}><Markdown remarkPlugins={[remarkGfm]}>{message.content}</Markdown></article>)}</section><Composer state={state}/></main>;}
